import { useCallback } from 'react';
import { JxChip, JxTagInput, useControllableState } from '@jinx-ui/react';

const EMPTY_TAGS: string[] = [];

export interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
}

export default function ArticleTagPicker({
  value,
  defaultValue = EMPTY_TAGS,
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
}: ArticleTagPickerProps) {
  const [tags, setTags] = useControllableState<string[]>(value, defaultValue, onChange);

  const handleChange = useCallback(
    (next: string[]) => {
      const normalized = next.map((tag) => tag.trim()).filter(Boolean);
      setTags(normalized.filter((tag, index) => normalized.indexOf(tag) === index));
    },
    [setTags],
  );

  const removeTag = (tag: string) => handleChange(tags.filter((item) => item !== tag));

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      <label className="jx-label" htmlFor="article-tags">
        {label}
      </label>
      <JxTagInput
        id="article-tags"
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={handleChange}
      />
      {tags.length === 0 ? (
        <p className="jx-input-help">Пока ничего не выбрано. Добавьте первый тег, чтобы статью было легче найти.</p>
      ) : (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}
        >
          {tags.map((tag) => (
            <span role="listitem" key={tag}>
              <JxChip removable onRemove={() => removeTag(tag)}>
                {tag}
              </JxChip>
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

